        "#Q4 Svm With  samoyed kernel\n",
        "#SVM Model\n",
        "#Import necessary libraries\n",
        "import numpy as np\n",
        "import matplotlib.pyplot as plt\n",
        "from sklearn import svm\n",
        "#sample data\n",
        "x = np.array([[1,2],[5,8],[1.5,1.8],[8,8],[1,0.6],[9,11]])\n",
        "y = [0,1,0,1,0,1]\n",
        "#Define the svm model with a sigmoid kernel\n",
        "clf = svm.SVC(kernel = 'sigmoid', gamma = 'auto', coef0=1)\n",
        "#fit the model\n",
        "clf.fit(x,y)\n",
        "#plot the decision function\n",
        "plt.figure(figsize=(8,6))\n",
        "plt.scatter(x[:, 0], x[:, 1], c=y, cmap = plt.cm.Paired, marker = 'o', s\n",
        "= 100)\n",
        "#plot the decision boundary and margins\n",
        "ax = plt.gca()\n",
        "xlim = ax.get_xlim()\n",
        "ylim = ax.get_ylim()\n",
        "#Create grid to evaluate model\n",
        "xx = np.linspace(xlim[0], xlim[1], 30)\n",
        "yy = np.linspace(ylim[0], ylim[1], 30)\n",
        "YY, XX = np.meshgrid(yy, xx)\n",
        "xy = np.vstack([XX.ravel(), YY.ravel()]).T\n",
        "Z = clf.decision_function(xy).reshape(XX.shape)\n",
        "#plot decision boundary and margins\n",
        "ax.contour(XX, YY, Z, colors='k', levels=[-1,0,1], alpha = 0.5,\n",
        "linestyles = ['--', '-', '--'])\n",
        "ax.scatter(clf.support_vectors_[:, 0], clf.support_vectors_[:,1], s\n",
        "=200, linewidth = 1, facecolors = 'none', edgecolors = 'k')\n",
        "plt.title(\"Support Vector Classifier with sigmoid kernel\")\n",
        "plt.xlabel('X1')\n",
        "plt.ylabel('X2')\n",
        "plt.show()"
